/**
 * Opportunities from “Global Opportunities — Open Now” (compiled 12 Oct 2026).
 * Only calls still open on 13 Oct 2026 (or rolling / opening soon) are kept;
 * entries already on the site, closed one-off calls and umbrella rows that are
 * not a single call were left out. Official application pages (checked in a
 * browser) are in applyLinks.js and banner photos in photos.js.
 */
import { make } from './listings-oct-2026'

const SOURCE = '“Global Opportunities — Open Now” (12 Oct 2026), compiled from official sources'

const ACRONYM = /^(China|Japan|Korea|India|Europe|European|AI|ICT|STEM|STEAM|HIV|UN|EU|UK|US|M&E|SDGs|WASH|GBV|NGOs?|CSOs?|SMEs?|Africa|African|Asia|Japan|Commonwealth|Global)\b/
const lowerFirst = (s = '') => (ACRONYM.test(s) ? s : s.charAt(0).toLowerCase() + s.slice(1))
const plus = (s = '') => {
  const parts = s.split(' + ')
  return parts.length > 1 ? `${parts.slice(0, -1).join(', ')} and ${parts.at(-1)}` : s
}
const field = (f) => (!f || /^all (disciplines|fields)/i.test(f) ? 'any field' : lowerFirst(f))
const LEVEL_NOUN = { Undergraduate: 'undergraduate', Graduate: "master's", PhD: 'PhD', Postgraduate: "master's or PhD", Postdoctoral: 'postdoctoral' }
const where = (country = '') => {
  const c = country.replace(/ \(.*\)$/, '')
  if (/international|global|worldwide|^africa|^europe|countries/i.test(c)) return ''
  return ` in ${/^(United|Netherlands|Philippines)/.test(c) ? 'the ' : ''}${c}`
}

function summarize(kind, o) {
  if (o.summary) return o.summary
  if (kind === 'scholarships')
    return `${plus(o.amount)} for ${LEVEL_NOUN[o.level] ?? lowerFirst(o.level)} study in ${field(o.focus)}${where(o.country)}.`
  if (kind === 'fellowships') return `A fellowship in ${field(o.focus)} for ${lowerFirst(o.who)}.`
  if (kind === 'grants') return `Grants for ${lowerFirst(o.who)} working on ${field(o.focus)}.`
  return `${o.org}: internships for students and recent graduates in ${field(o.focus)}, based in ${o.country}.`
}

export function build(kind, o, source = SOURCE) {
  const { opens, dates = [], ...rest } = o
  return make(kind, {
    ...rest,
    coverage: o.amount,
    dates: opens || dates.length ? [...(opens ? [{ date: opens, label: 'Applications open' }] : []), ...dates] : undefined,
    summary: summarize(kind, o),
    source,
  })
}

